#!/bin/bash
# ═══════════════════════════════════════════════════════════════════════════════
# USER status line override — Dom, 2026-08-20 ("reduce the status lines/box,
# it's too busy").
#
# WHY A WRAPPER, NOT A FORK: LIFEOS/LIFEOS_StatusLine.sh is SYSTEM-owned and gets
# regenerated by LifeOS tooling. Editing it directly means the trim is silently
# reverted on the next regen. Forking the whole 2862-line script means inheriting
# none of its upstream fixes. So we run the system renderer unchanged and drop
# the lines we don't want from its OUTPUT. Upstream improvements flow through;
# the trim survives regen.
#
# Kept: header (location/time/session), version+model, CONTEXT bar, usage limits,
# and any live-agent dispatch lines.
# Dropped: STATE meter, effort scale, model-mix roster, context-file breakdown,
# account email, and the redundant separator rules.
#
# Escape hatch: LIFEOS_SL_VERBOSE=1 passes the system output through untouched.
# ═══════════════════════════════════════════════════════════════════════════════

set -o pipefail

if [ -z "$HOME" ]; then
    HOME="$(getent passwd "$(id -un)" 2>/dev/null | cut -d: -f6)"
fi

SYSTEM_STATUSLINE="${HOME}/.claude/LIFEOS/LIFEOS_StatusLine.sh"

# Fail visibly rather than rendering a blank status line.
if [ ! -r "$SYSTEM_STATUSLINE" ]; then
    printf 'LifeOS │ statusline missing: %s\n' "$SYSTEM_STATUSLINE"
    exit 0
fi

# stdin is the JSON payload from Claude Code; pass it straight through.
_raw="$(bash "$SYSTEM_STATUSLINE")"

if [ "${LIFEOS_SL_VERBOSE:-0}" = "1" ]; then
    printf '%s\n' "$_raw"
    exit 0
fi

# Filter on the ANSI-stripped twin so color codes never break a match, but emit
# the original colored line.
printf '%s\n' "$_raw" | while IFS= read -r _line; do
    _plain=$(printf '%s' "$_line" | sed 's/\x1b\[[0-9;]*m//g')

    case "$_plain" in
        # ── Dropped content lines ───────────────────────────────────────────
        STATE:*)              continue ;;   # dimension meters
        ⚡*)                   continue ;;   # static effort scale
        *"STARTUP LOAD:"*)    continue ;;   # context-file breakdown tail
        *@*.*)                                # account email
            case "$_plain" in
                *" "*) ;;                     # a sentence, not an address
                *) continue ;;
            esac
            ;;
    esac

    # Model-mix roster: a bare run of model names with no label.
    case "$_plain" in
        HAIKU*|*"SONNET "*"OPUS "*) continue ;;
    esac

    # Indented context-file entries, e.g. "  SKILLS(9.0%), CLAUDE.md(0.9%)".
    case "$_plain" in
        "  "*"%)"*) continue ;;
    esac

    # ── Separator rules ─────────────────────────────────────────────────────
    # Keep the dashed rule under the header; drop solid and dotted rules, which
    # only framed the sections we just removed.
    _stripped=$(printf '%s' "$_plain" | tr -d ' ')
    case "$_stripped" in
        ─*)  continue ;;
        ·*)  continue ;;
        "")  continue ;;   # blank lines left behind by dropped sections
    esac

    printf '%s\n' "$_line"
done
